import{_ as e,c as a,o as d,a5 as i}from"./chunks/framework.CUh81O5y.js";const u=JSON.parse('{"title":"Tags","description":"","frontmatter":{},"headers":[],"relativePath":"apps/cloud/device-settings/tags.md","filePath":"apps/cloud/device-settings/tags.md"}'),r={name:"apps/cloud/device-settings/tags.md"};function o(n,t,s,c,g,p){return d(),a("div",{"data-pagefind-body":!0},t[0]||(t[0]=[i('<h1 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h1><p>The tags feature enables arbitrary key-value pairs (tags) to be associated with a device.</p><p>Tags appear in the device list, and can be used to filter devices, as well as appearing in reports.</p><p>Some are provided by default.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/STjaikd.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="user-tags" tabindex="-1">User tags <a class="header-anchor" href="#user-tags" aria-label="Permalink to &quot;User tags&quot;">​</a></h2><p>User tags are tags that are set by the user, and can be anything you like (within reason).</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/x6Vq0gm.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>To add a tag, type in the empty <code>Tag name</code> and <code>Tag Value</code> fields.</p><p>A summary of your tag changes will be shown.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/yup6WYH.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Clicking on <code>Save</code> will save the tags to the device.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/pZ7ZDlp.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="auto-generated-tags" tabindex="-1">Auto-Generated tags <a class="header-anchor" href="#auto-generated-tags" aria-label="Permalink to &quot;Auto-Generated tags&quot;">​</a></h2><p>The auto-generated tags are tags that are set by the system, and cannot be changed.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/8ZA0ajA.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>Common auto-generated tags include:</p><table tabindex="0"><thead><tr><th>Tag name</th><th>Description</th></tr></thead><tbody><tr><td>Type</td><td>Type of the device</td></tr><tr><td>id</td><td>The device&#39;s unique identifier</td></tr><tr><td>sn</td><td>The device&#39;s serial number</td></tr><tr><td>is</td><td>Generic tag, primarily used to show a device is <code>nearby</code> when using a mobile app with Bluetooth enabled and a Bluetooth enabled device</td></tr><tr><td>warning</td><td>Is the device in a warning state, <code>LowBattery</code> or <code>NoConnection</code></td></tr><tr><td>LastSeen</td><td>The time category the device was last seen in <code>&lt;24H</code>, <code>&lt;3D</code>, <code>&lt;7D</code></td></tr><tr><td>ignition</td><td>Is the device&#39;s ignition on or off (for devices that support this)</td></tr><tr><td>state</td><td>The devices current mode, <code>Tracking</code>, <code>Sleep</code>, <code>Alert</code>, <code>Flight Mode</code>...</td></tr><tr><td>zone</td><td>Zones that the device is currently in</td></tr><tr><td>SafeZone</td><td>Is the device <code>inside</code> or <code>outside</code> a safe zone</td></tr><tr><td>lastZoneList</td><td>see inventory reporting...</td></tr><tr><td>timeSinceFirstEntry</td><td>see inventory reporting...</td></tr><tr><td>currentZoneList</td><td>see inventory reporting...</td></tr><tr><td>timeInZone</td><td>see inventory reporting...</td></tr></tbody></table>',18)]))}const h=e(r,[["render",o]]);export{u as __pageData,h as default};
